declare(strict_types=1);require_once __DIR__.'/billing_common.php';$user=billing_require_admin();production_require_method('POST');$in=production_input();accounts_endpoint(function()use($user,$in):array{$db=production_db();return accounts_transaction($db,function()use($db,$user,$in):array{$client=billing_client($db,$in['client_id']??0);$bank=(int)($in['bank_account_id']??0);$b=$db->prepare("SELECT id FROM qbook_bank_accounts WHERE id=? AND is_active=1");$b->execute([$bank]);if(!$b->fetch())accounts_fail('ACTIVE_BANK_ACCOUNT_REQUIRED');$dest=strtoupper((string)($in['destination']??'TRADE_RECEIVABLES'));if(!in_array($dest,['TRADE_RECEIVABLES','CUSTOMER_ADVANCES'],true))accounts_fail('INVALID_RECEIPT_DESTINATION');$ref=billing_allocate_reference($db,'qbook_customer_receipt_references');$db->prepare("INSERT INTO qbook_customer_receipts(reference_no,client_id,client_name_snapshot,bank_account_id,receipt_date,cash_amount,bank_reference,narration,destination,created_by)VALUES(?,?,?,?,?,?,?,?,?,?)")->execute([$ref,$client['id'],$client['name'],$bank,accounts_date($in['receipt_date']??''),accounts_minor_decimal(accounts_money_minor($in['cash_amount']??'')),production_clean_text($in['bank_reference']??'',150,'INVALID_BANK_REFERENCE',false)?:null,production_clean_text($in['narration']??'',500,'INVALID_NARRATION',false)?:null,$dest,$user['id']]);$id=(int)$db->lastInsertId();accounts_audit($db,$user,'CUSTOMER_RECEIPT_DRAFT_SAVED','CUSTOMER_RECEIPT',$id);return['receipt'=>['id'=>$id,'reference'=>billing_ref('RECEIPT',$ref),'status'=>'DRAFT']];});});
